# Generated by cmd/release in airiclenz/apogee and overwritten at each release: edit
# cmd/release/templates/apogee.rb.tmpl there, never this file.
class Apogee < Formula
  desc "Terminal coding agent built for smaller local models, better with bigger ones"
  homepage "https://github.com/airiclenz/apogee"
  version "0.26.0"
  license "MIT"

  # Installs the prebuilt binary for this platform rather than compiling, so no Go
  # toolchain is needed. The tree is CGO-free and every OS-specific confinement
  # backend sits behind a build tag, so all six release targets come off one
  # `cmd/release dist` in the project repo.
  on_macos do
    on_arm do
      url "https://github.com/airiclenz/apogee/releases/download/v0.26.0/apogee_0.26.0_darwin_arm64.tar.gz"
      sha256 "0a05b6dcfff1136bc792ac9bebaa83fbec446f69d3c35b366b3c4626fc202eae"
    end
    on_intel do
      url "https://github.com/airiclenz/apogee/releases/download/v0.26.0/apogee_0.26.0_darwin_amd64.tar.gz"
      sha256 "aa6a2aef8451daaa209b64c38de68f118aa547bf67554342d481bd7fcdcfb855"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/airiclenz/apogee/releases/download/v0.26.0/apogee_0.26.0_linux_arm64.tar.gz"
      sha256 "066e69f1a3bdda6f41f8fa012eed8b56e8295208eb06585fa01da24711ac22fe"
    end
    on_intel do
      url "https://github.com/airiclenz/apogee/releases/download/v0.26.0/apogee_0.26.0_linux_amd64.tar.gz"
      sha256 "8e2f06899750e69a9a1fc0e400159abd7d4aef55b11eb12c3cb10a678cb3e69e"
    end
  end

  def install
    bin.install "apogee"
  end

  def caveats
    <<~EOS
      apogee needs an OpenAI-compatible endpoint — a local server (llama.cpp, Ollama,
      LM Studio, vLLM) needs no API key:

        apogee --endpoint http://localhost:8080 --model <name>

      `apogee probe` reports what this host can enforce for Auto mode, for free and
      without calling a model.
    EOS
  end

  test do
    # --version prints "apogee version vX.Y.Z+<build provenance>".
    assert_match version.to_s, shell_output("#{bin}/apogee --version")
    assert_match "apogee", shell_output("#{bin}/apogee --help")
  end
end
